package com.ngocdevv.nativecook.blocks.onboarding.metacardunifyfan

import android.util.Base64

/** Embedded originals keep this block portable without app-level resource registration. */
internal object MetacardAssetData {
    fun bytes(name: String): ByteArray = Base64.decode(when (name) {
        "Inter-Bold.ttf" -> Inter_Bold_ttf()
        "Inter-Regular.ttf" -> Inter_Regular_ttf()
        "card-0.png" -> card_0_png()
        "card-1.png" -> card_1_png()
        "card-2.png" -> card_2_png()
        "card-3.png" -> card_3_png()
        "card-4.png" -> card_4_png()
        "card-5.png" -> card_5_png()
        "card-6.png" -> card_6_png()
        "card-7.png" -> card_7_png()
        "card-shadow.png" -> card_shadow_png()
        "hero-chip.png" -> hero_chip_png()
        else -> error("Unknown Metacard asset: $name")
    }, Base64.DEFAULT)
    private fun Inter_Bold_ttf(): String = arrayOf(
